{
  "task_intro": "You are assisting a constrained bi-objective optimizer. Your goal is to choose the most informative high-fidelity evaluations under limited budget.",
  "problem_intro": "This is a two-objective constrained design problem. Lower objective values are preferred. A candidate is feasible only when all constraints are satisfied. The true formulas are hidden.",
  "task": {
    "obj_dirs": {"f1": "minimize", "f2": "minimize"},
    "constraint_rule": "For every constraint, predicted_value <= 0 means predicted feasible, and predicted_value > 0 means predicted violated.",
    "metric_def": "p_nd means the current surrogate-based probability that a candidate is non-dominated with respect to a specific objective view. hfe means high-fidelity evaluated. ocsp means overall constraint satisfaction probability."
  },
  "notes": [
    "Candidate labels are stable identifiers. Use them exactly as given.",
    "Some targets may already been evaluated with high-fidelity. Do not request them again.",
    "Only targets evaluated with high-fidelity consume budget, low-fidelity targets do not consume budget.",
    "nearest_history_points lists at most 3 later infill points in normalized design space. Initial DOE points are excluded; their landscape coverage is already reflected in the surrogate uncertainty of this candidate. Let d1 be the RMS distance to the nearest remaining historical infill. Keep a neighbor only if its RMS distance is <= 1.5 * d1. If fewer than 3 points qualify, list fewer; if there is no later infill history, use an empty list. Only high-fidelity evaluated values are shown there; value=null means that target has not been high-fidelity evaluated for that historical point.",
    "Overall feasibility is determined by satisfying all constraints at the same time. A candidate is truly feasible only if every constraint value is <= 0."
  ],
  "budget": {
    "current_cost_used": 100,
    "cost_used_since_initial_doe": 0,
    "total_budget": 250,
    "remaining_budget": 150,
    "fillup_cost_for_full_generation": 50,
    "budget_pressure_ratio": 0
  },
  "targets": {
    "objectives": [
      {"name": "f1", "evaluation_cost": 0.15},
      {"name": "f2", "evaluation_cost": 0.05}
    ],
    "constraints": [
      {"name": "g1", "evaluation_cost": 0.7},
      {"name": "g2", "evaluation_cost": 0.1}
    ]
  },
  "candidates": [
    {
      "label": "candidate_A",
      "x": [1.0404, 0.122],
      "objectives": {
        "f1": {"predicted_value": 1.0404, "uncertainty": 1.7211e-15, "p_nd": 1, "already_hfe": false},
        "f2": {"predicted_value": 0.122, "uncertainty": 1.9071e-15, "p_nd": 0, "already_hfe": false}
      },
      "constraints": {
        "g1": {"predicted_value": -0.03, "uncertainty": 0.0793, "satisfied_if_prediction_is_exact": true, "constraint_zscore": 0.3787, "already_hfe": false},
        "g2": {"predicted_value": -0.1302, "uncertainty": 9.421e-15, "satisfied_if_prediction_is_exact": true, "constraint_zscore": 1e6, "already_hfe": false}
      },
      "ocsp": 0.6475,
      "nearest_history_points": [
        {
          "distance": 0.041,
          "closer_than_fraction": 0.97,
          "x": [1.01, 0.16],
          "objectives": {
            "f1": {"high_fidelity_evaluated": true, "value": 1.01},
            "f2": {"high_fidelity_evaluated": true, "value": 0.16}
          },
          "constraints": {
            "g1": {"high_fidelity_evaluated": true, "value": -0.021},
            "g2": {"high_fidelity_evaluated": false, "value": null}
          }
        },
        {
          "distance": 0.058,
          "closer_than_fraction": 0.91,
          "x": [0.98, 0.19],
          "objectives": {
            "f1": {"high_fidelity_evaluated": true, "value": 0.98},
            "f2": {"high_fidelity_evaluated": false, "value": null}
          },
          "constraints": {
            "g1": {"high_fidelity_evaluated": true, "value": 0.014},
            "g2": {"high_fidelity_evaluated": true, "value": -0.44}
          }
        }
      ]
    },
    ...
    {
      "label": "candidate_J",
      "x": [0.7852, 0.5972],
      "objectives": { "...": "same fields as candidate_A" },
      "constraints": { "...": "same fields as candidate_A" },
      "ocsp": 0.9997,
      "nearest_history_points": []
    }
  ],
  "batch_condition": "There are 5 prompts in total for a generation, each prompt contains randomly selected 10 candidates.So try to make the best use of budget as there are 40 candidates in other prompts needed to be planned.",
  "request": {
    "scope": "Every candidate shown here has already been selected by the original optimizer. Do not decide candidate inclusion or exclusion. Only decide which objectives and constraints, if any, deserve high-fidelity evaluation for each shown candidate. Empty lists are allowed.",
    "n_candidates_in_batch": 10,
    "allowed_targets_per_candidate": "You may request zero or more objectives and zero or more constraints for each selected candidate."
  },
  "output": {
    "format": "Return JSON only. Do not use markdown.",
    "example schema": {
      "selections": [
        {"label": "candidate_A", "evaluate_objectives": ["f1", "f2"], "evaluate_constraints": []}
      ]
    },
    "rules": [
      "The objectives and constraints you put in the brackets will be evaluated with high-fidelity and consume budget, otherwise will be evaluated with low-fidelity and not consume budget,",
      "Use labels and target names exactly as provided.",
      "Do not output indices. Do not give any explanation.",
      "Return a decision for every candidate shown in this batch.",
      "Empty objective and constraint lists are allowed when no high-fidelity evaluation is needed.",
      "Return valid JSON that can be parsed directly."
    ]
  }
}
